import java.util.*;
import java.io.*;

public class Main {
    static Map<Long, Long> cacheMap = new HashMap<>();

    static long countDigitsLong(long x) {
        long cnt = 0;
        while (x != 0) {
            cnt++;
            x /= 10;
        }
        return cnt;
    }

    static long reverseNumber(long x) {
        long[] digits = new long[17];
        int pos = 0;
        long tempX = x;
        while (tempX != 0) {
            digits[pos++] = (tempX % 10) - (tempX < 0 ? -1 : 1);
            tempX /= 10;
        }
        long res = 0;
        for (int i = pos - 1; i >= 0; i--) {
            res = res * 10 + digits[i];
        }
        return res;
    }

    static long previousValueLong(long x) {
        long c = 0;
        long orig = x;
        while (x != 0) {
            c *= 10;
            c += (x < 0 ? -1 : 1);
            x /= 10;
        }
        c *= 10;
        c++;
        return orig - c;
    }

    static long lastDigitLong(long x) {
        while (x >= 10) {
            x /= 10;
        }
        return x;
    }

    static long deleteLeadingLong(long x) {
        long[] digits = new long[17];
        int p = 0;
        long tempX = x;
        while (tempX >= 10) {
            digits[p++] = tempX % 10;
            tempX /= 10;
        }
        long res = 0;
        for (int i = p - 1; i >= 0; i--) {
            res = res * 10 + digits[i];
        }
        return res;
    }

    static long computeValue(long x) {
        if (x <= 11) {
            return Math.min(13 - x, x);
        }
        if (cacheMap.containsKey(x))
            return cacheMap.get(x);
        long n = 0, t = 1;
        while (t < x) {
            t = t * 10 + 1;
            n++;
        }
        if (x * 2 >= t) {
            long res = Math.min(computeValue(t - x) + n + 1, (x / (t / 10)) * n + computeValue(x % (t / 10)));
            cacheMap.put(x, res);
            return res;
        }
        long res = (x / (t / 10)) * n + computeValue(x % (t / 10));
        cacheMap.put(x, res);
        return res;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        long a = Long.parseLong(br.readLine().trim());
        System.out.println(computeValue(a));
    }
}
